Path('test/autotest-download-v05710.test.js').write_text(r'''import test from "node:test";
import assert from "node:assert/strict";
import {autotestDownloadHttpUrl,requestAutotestBrowserDownload} from "../src/autotest-download.js";
class FakeBlob{constructor(parts,opt={}){this.body=parts.join("");this.type=opt.type||"";this.size=Buffer.byteLength(this.body)}}
function fakeDocument(){const clicks=[];const host={appendChild(a){a.parentNode=host}};return {clicks,documentImpl:{body:host,createElement(){return {style:{},click(){clicks.push({href:this.href,download:this.download})},remove(){this.parentNode=null}}}}}}
test("v0.57.10 controlled browser uses same-origin HTTP attachment on first click",()=>{const d=fakeDocument(),artifact={filename:"Elyndra-autotest-worlds-v0.57.10-proof.json",mime:"application/json;charset=utf-8",body:'{"worlds":[1,2]}'};const result=requestAutotestBrowserDownload(artifact,{documentImpl:d.documentImpl,navigatorImpl:{serviceWorker:{controller:{}}},locationImpl:{href:"https://example.test/Elyndra/"},nowImpl:()=>123});assert.equal(result.method,"service-worker-http");assert.equal(result.bridgeControlled,true);assert.equal(d.clicks.length,1);assert.equal(d.clicks[0].download,artifact.filename);assert.match(d.clicks[0].href,/\/Elyndra\/__elyndra_autotest_download__\?/);assert.match(d.clicks[0].href,/filename=Elyndra-autotest-worlds-v0\.57\.10-proof\.json/)});
test("v0.57.10 URL builder keeps filename and cache-bypass nonce",()=>{const url=new URL(autotestDownloadHttpUrl({filename:"debug.json"},{baseHref:"https://example.test/Elyndra/index.html",nonce:456}));assert.equal(url.pathname,"/Elyndra/__elyndra_autotest_download__");assert.equal(url.searchParams.get("filename"),"debug.json");assert.equal(url.searchParams.get("v"),"57010");assert.equal(url.searchParams.get("n"),"456")});
test("v0.57.10 keeps blob fallback only for uncontrolled browsers",()=>{const d=fakeDocument(),made=[],revoked=[],URLImpl={createObjectURL(blob){made.push(blob);return "blob:fallback"},revokeObjectURL(url){revoked.push(url)}};const result=requestAutotestBrowserDownload({filename:"debug.json",mime:"application/json",body:'{"ok":true}'},{BlobImpl:FakeBlob,URLImpl,documentImpl:d.documentImpl,navigatorImpl:{serviceWorker:{controller:null}},locationImpl:{href:"https://example.test/Elyndra/"},setTimeoutImpl:fn=>{fn();return 1}});assert.equal(result.method,"blob-url");assert.equal(result.bridgeControlled,false);assert.equal(made.length,1);assert.deepEqual(revoked,["blob:fallback"])});
''',encoding='utf-8')

Path('scripts/prove-autotest-iab-download-browser.mjs').write_text(r'''import assert from "node:assert/strict";
import http from "node:http";
import {readFile,writeFile,mkdtemp,rm} from "node:fs/promises";
import {join,normalize,extname} from "node:path";
import {tmpdir} from "node:os";
import {createHash} from "node:crypto";
import {chromium} from "playwright";
const root=process.cwd(),port=4178,origin=`http://127.0.0.1:${port}`;
const mime={'.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.html':'text/html; charset=utf-8','.json':'application/json; charset=utf-8','.css':'text/css; charset=utf-8'};
const fixture=`<!doctype html><meta charset="utf-8"><button id="debug">debug</button><button id="world">world</button><script type="module">
import {buildAutotestExportSnapshot,buildAutotestExportArtifacts,saveLastAutotestExportSnapshot} from "/src/autotest-export.js?v=57010";
import {buildAutotestDownloadPayload,ensureAutotestDownloadBridge,requestAutotestBrowserDownload} from "/src/autotest-download.js?v=57010";
const results=[1,2].map(index=>({index,status:"COMPLETED",stopReason:"TURN_LIMIT",summary:{index},world:{formatVersion:1,world:{id:"W"+index,name:"世界"+index},player:{name:"P"+index}}}));
const snapshot=buildAutotestExportSnapshot({appVersion:"0.57.10",report:{summary:{worldsRequested:2,totalTurns:60}},results,createdAt:"2026-09-25T04:30:00.000Z",exportMode:"both"});
await saveLastAutotestExportSnapshot(snapshot);const artifacts=buildAutotestExportArtifacts(snapshot);const expected={};for(const kind of ["debug","world"]){const p=await buildAutotestDownloadPayload(artifacts[kind]);expected[kind]={filename:p.filename,bytes:p.bytes,sha256:p.sha256,body:p.body}}
const bridge=await ensureAutotestDownloadBridge({scriptUrl:"/autotest-export-sw.js?v=57010",scope:"/",timeoutMs:5000});window.__bridge=bridge;window.__expected=expected;window.__requests={};
for(const kind of ["debug","world"])document.querySelector("#"+kind).addEventListener("click",()=>{window.__requests[kind]=requestAutotestBrowserDownload(artifacts[kind])});window.__ready=true;
</script>`;
const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,origin);if(u.pathname==="/proof.html"){res.writeHead(200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"});res.end(fixture);return}const rel=normalize(decodeURIComponent(u.pathname)).replace(/^[/\\]+/,"");if(rel.includes("..")){res.writeHead(403);res.end();return}const file=join(root,rel),body=await readFile(file);res.writeHead(200,{"Content-Type":mime[extname(file)]||"application/octet-stream","Cache-Control":"no-store"});res.end(body)}catch{res.writeHead(404);res.end("not found")}});
await new Promise(resolve=>server.listen(port,"127.0.0.1",resolve));const out=await mkdtemp(join(tmpdir(),"elyndra-v05710-"));
try{const browser=await chromium.launch({headless:true});const context=await browser.newContext({acceptDownloads:true});const page=await context.newPage();await page.goto(origin+"/proof.html",{waitUntil:"domcontentloaded"});await page.waitForFunction(()=>window.__ready===true&&navigator.serviceWorker?.controller&&window.__bridge?.controlled===true,{timeout:10000});
for(const kind of ["debug","world"]){const expected=await page.evaluate(k=>window.__expected[k],kind),wait=page.waitForEvent("download",{timeout:10000});await page.click("#"+kind);const download=await wait;assert.equal(download.suggestedFilename(),expected.filename);const path=join(out,expected.filename);await download.saveAs(path);const bytes=await readFile(path),sha=createHash("sha256").update(bytes).digest("hex");assert.equal(bytes.length,expected.bytes);assert.equal(sha,expected.sha256);assert.equal(bytes.toString("utf8"),expected.body);const request=await page.evaluate(k=>window.__requests[k],kind);assert.equal(request.method,"service-worker-http");assert.equal(request.bridgeControlled,true);console.log(`IAB_HTTP_FIRST_CLICK PASS kind=${kind} filename=${expected.filename} bytes=${bytes.length} sha256=${sha}`)}await browser.close()}finally{server.close();await rm(out,{recursive:true,force:true})}
''',encoding='utf-8')

Path('docs/releases/v0.57.10.md').write_text('''# Elyndra v0.57.10\n\nIAB download delivery hardening.\n\n- AutoTest Debug/world downloads now prefer a same-origin Service Worker HTTP attachment response with `Content-Disposition`, avoiding `blob:` delivery when the page is controlled.\n- The bridge registers at module load, uses `skipWaiting()` + `clients.claim()`, and serves the already-persisted IndexedDB AutoTest snapshot without rerunning a test.\n- Blob/object-URL delivery remains a fallback only when Service Worker control is unavailable.\n- Added unit coverage for HTTP-vs-Blob selection and a real Chromium first-click regression that writes both Debug and 2-world bundle files to disk, then verifies exact bytes and SHA-256.\n''',encoding='utf-8')
